// Created: 2026-08-22

// Guards #3645: the CC-adoption board is published history, but it was generated
// from shared/cc-adoption-gaps.json, a WORK QUEUE that cc-release-watch.mjs
// prunes every run. Generating by replacement meant a prune deleted published
// waves. Measured 2026-08-21: 18 waves on main, 2 at the nightly PR's head, so
// regenerating there would have published a 2-wave board and dropped 16 waves of
// history. It also left that PR permanently red, blocking #3644.
//
// The invariant under test is simple and load-bearing: merging can ADD a version
// and can UPDATE a version, but can never DROP one.

import { describe, expect, it } from "vitest";
import {
	compareVersionsDesc,
	mergeWaves,
} from "../scripts/merge-adoption-waves.mjs";

const wave = (version: string, slug = "f") => ({
	version,
	features: [
		{ slug, category: "c", description: "d", gapScore: 1, affectedSkills: [] },
	],
});

describe("compareVersionsDesc", () => {
	it("orders numerically, not lexically", () => {
		// The bug this pins: "2.1.9" > "2.1.10" as strings, which would file a
		// newer release below an older one on a page that reads newest-first.
		expect(["2.1.10", "2.1.9"].sort(compareVersionsDesc)).toEqual([
			"2.1.10",
			"2.1.9",
		]);
		expect(["2.1.219", "2.1.238", "2.1.232"].sort(compareVersionsDesc)).toEqual([
			"2.1.238",
			"2.1.232",
			"2.1.219",
		]);
	});

	it("tolerates uneven segment counts", () => {
		expect(compareVersionsDesc("2.2", "2.1.9")).toBeLessThan(0);
		expect(compareVersionsDesc("2.1", "2.1.0")).toBe(0);
	});
});

describe("mergeWaves never loses a published version", () => {
	it("carries forward waves the pruned queue no longer mentions", () => {
		const published = ["2.1.238", "2.1.237", "2.1.236", "2.1.235"].map((v) => wave(v));
		const pruned = [wave("2.1.238")]; // the queue after a real prune
		const merged = mergeWaves(published, pruned);
		expect(merged).toHaveLength(4);
		expect(merged.map((w) => w.version)).toEqual([
			"2.1.238",
			"2.1.237",
			"2.1.236",
			"2.1.235",
		]);
	});

	it("reproduces the exact 18-to-2 collapse that broke #3644", () => {
		const published = Array.from({ length: 18 }, (_, i) => wave(`2.1.${238 - i}`));
		const merged = mergeWaves(published, [wave("2.1.238"), wave("2.1.232")]);
		expect(merged).toHaveLength(18);
	});

	it("adds a genuinely new version", () => {
		const merged = mergeWaves([wave("2.1.238")], [wave("2.1.239")]);
		expect(merged.map((w) => w.version)).toEqual(["2.1.239", "2.1.238"]);
	});

	it("lets fresh queue data win for a version present in both", () => {
		// A re-analysis must be able to correct a published wave, otherwise the
		// board freezes the first answer forever.
		const merged = mergeWaves([wave("2.1.238", "stale")], [wave("2.1.238", "fresh")]);
		expect(merged).toHaveLength(1);
		expect(merged[0]?.features[0]?.slug).toBe("fresh");
	});

	it("is idempotent, so a CI rebuild produces identical bytes", () => {
		// The drift gate regenerates and diffs. A merge that reordered or grew on
		// a second pass would make every PR red for no reason.
		const published = [wave("2.1.238"), wave("2.1.236")];
		const queue = [wave("2.1.237")];
		const once = mergeWaves(published, queue);
		expect(mergeWaves(once, queue)).toEqual(once);
	});

	it("handles an empty published board (fresh clone) and an empty queue", () => {
		expect(mergeWaves([], [wave("2.1.1")])).toHaveLength(1);
		expect(mergeWaves([wave("2.1.1")], [])).toHaveLength(1);
		expect(mergeWaves(undefined, undefined)).toEqual([]);
	});
});
